        e := l.Front()
        for position != 0 {      //获取相对位置
            position--
            e = e.Next()
        }
        l.MoveBefore(mark, e)    //移动位置

    }
    res := [][]int{}
    for e := l.Front(); e != nil; e = e.Next() {
        res = append(res, e.Value.([]int))
    }
    return res
